1	package gitutil
2	
3	import (
4		"context"
5		"fmt"
6		"strings"
7	)
8	
9	// CommitCheckpoints pairs one commit with the checkpoint IDs its message
10	// carries in Entire-Checkpoint trailers. Most commits carry zero or one.
11	type CommitCheckpoints struct {
12		Commit      string
13		Subject     string
14		Checkpoints []string
15	}
16	
17	// CheckpointTrailersInRange lists the commits reachable from head but not
18	// base, newest first, together with any Entire-Checkpoint trailer values on
19	// each. Commits without a trailer are still returned so callers can report
20	// "no checkpoint" honestly rather than silently dropping the commit.
21	func CheckpointTrailersInRange(ctx context.Context, repo, base, head string) ([]CommitCheckpoints, error) {
22		// %x00 separates fields and %x01 terminates records, so a subject line can
23		// hold any printable text. Git joins several trailer values with the
24		// requested separator (a comma).
25		format := "%H%x00%s%x00%(trailers:key=Entire-Checkpoint,valueonly,separator=%x2C)%x01"
26		out, err := run(ctx, repo, "git", "log", "--format="+format, base+".."+head)
27		if err != nil {
28			return nil, err
29		}
30		var result []CommitCheckpoints
31		for _, record := range strings.Split(out, "\x01") {
32			record = strings.TrimSpace(record)
33			if record == "" {
34				continue
35			}
36			parts := strings.SplitN(record, "\x00", 3)
37			if len(parts) < 2 {
38				continue
39			}
40			entry := CommitCheckpoints{Commit: strings.TrimSpace(parts[0]), Subject: parts[1]}
41			if len(parts) == 3 {
42				for _, id := range strings.Split(parts[2], ",") {
43					id = strings.TrimSpace(id)
44					if id != "" {
45						entry.Checkpoints = append(entry.Checkpoints, id)
46					}
47				}
48			}
49			result = append(result, entry)
50		}
51		return result, nil
52	}
53	
54	// CheckpointRef resolves the per-checkpoint ref for an ID without assuming
55	// the shard scheme: it matches refs/entire/checkpoints/*/<id> and returns the
56	// first hit. ok is false when the repository has no such ref, which happens
57	// when the checkpoint lives only on a remote or the commit predates
58	// checkpoints.
59	func CheckpointRef(ctx context.Context, repo, checkpointID string) (ref string, ok bool, err error) {
60		if checkpointID == "" || strings.ContainsAny(checkpointID, "/ \t\r\n*?[]\\") {
61			return "", false, fmt.Errorf("invalid checkpoint id %q", checkpointID)
62		}
63		out, err := run(ctx, repo, "git", "for-each-ref", "--format=%(refname)", "refs/entire/checkpoints/*/"+checkpointID)
64		if err != nil {
65			return "", false, err
66		}
67		for _, line := range strings.Split(out, "\n") {
68			line = strings.TrimSpace(line)
69			if line != "" {
70				return line, true, nil
71			}
72		}
73		return "", false, nil
74	}
